/* Standalone design prototype. All objects, observations and routes below are synthetic. */
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const escapeHTML = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const houses = [
  {id:'demo-house-1', address:'проспект Мира, 10', area:'Центральный район', type:'Контур здания · демо-объект 01', x:29.3, y:41.9},
  {id:'demo-house-2', address:'ул. Ленина, 28', area:'Центральный район', type:'Контур здания · демо-объект 02', x:70.4, y:30.5},
  {id:'demo-house-3', address:'проспект Мира, 20', area:'Центральный район', type:'Контур здания · демо-объект 03', x:42, y:39},
  {id:'demo-house-4', address:'ул. Карла Маркса, 21', area:'Центральный район', type:'Контур здания · демо-объект 04', x:58, y:55},
  {id:'demo-house-5', address:'ул. Вейнбаума, 12', area:'Центральный район', type:'Контур здания · демо-объект 05', x:37, y:66}
];
const destinations = [
  {id:'demo-goal-work',label:'Работа',address:'ул. Карла Маркса, 21',x:56,y:66},
  {id:'demo-goal-study',label:'Университет',address:'проспект Мира, 82',x:15,y:58},
  {id:'demo-goal-sport',label:'Спорт',address:'ул. Ленина, 56',x:83,y:52}
];
const state = {scenario:'places',a:null,b:null,active:'a',radius:500,mode:'walking',tab:'overview',view:'results',goals:[],standaloneGoals:[],start:null,point:null,pointReady:false,profiles:{a:'empty',b:'empty'},trips:{},standaloneTrips:{},selectedTrip:null,detail:null,collapsed:false,refined:{},pick:null,mapZoom:false,run:0,profileRuns:{a:0,b:0},pointRun:0,failNext:false,mobileSetup:false};
const dialog = $('#dialog');
let returnFocus = null;
let toastTimer;
const selectedGoals = () => state.scenario === 'standalone' ? state.standaloneGoals : state.goals;
const selectedTrips = () => state.scenario === 'standalone' ? state.standaloneTrips : state.trips;
const selectedSides = () => state.scenario === 'standalone' ? (state.start ? ['s'] : []) : ['a','b'].filter(s=>state[s]);
const getHouse = s => s === 's' ? state.start : state[s];
const sideLabel = s => s === 'b' ? 'Б' : s === 'a' ? 'А' : 'Старт';
const badge = (s, small='') => `<span class="badge ${s==='b'?'b':''} ${small}">${sideLabel(s)}</span>`;
const goalBadge = n => `<span class="badge goal">${n+1}</span>`;
const modeSwitch = () => `<div class="seg mode" role="group" aria-label="Общий режим поездок"><button data-action="mode" data-value="walking" class="${state.mode==='walking'?'selected':''}" aria-pressed="${state.mode==='walking'}"><span aria-hidden="true">♧</span> Пешком</button><button data-action="mode" data-value="driving" class="${state.mode==='driving'?'selected':''}" aria-pressed="${state.mode==='driving'}"><span aria-hidden="true">▱</span> Авто</button></div>`;
function announce(text){$('#announcer').textContent=text;}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3600);announce(text);}
function openDialog(title,subtitle,body,footer=''){
  if(!dialog.open) returnFocus=document.activeElement;
  $('#dialog-content').innerHTML=`<div class="dialog-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close-dialog" aria-label="Закрыть окно">×</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;
  if(!dialog.open)dialog.showModal();
}
function closeDialog(){dialog.close();if(returnFocus?.isConnected)returnFocus.focus();else $('.scenario-nav .selected').focus();}
dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function candidate(s){const h=state[s];return h?`<div class="candidate ${state.active===s?'active':''} ${s==='b'?'is-b':''}"><button class="candidate-main" data-action="select-side" data-side="${s}" aria-pressed="${state.active===s}" aria-label="Выбрать адрес ${sideLabel(s)}: ${h.address}">${badge(s)}<span class="candidate-copy"><strong>${h.address}</strong><small>${state.profiles[s]==='loading'?'Загружаем профиль…':h.area}</small></span></button><button class="candidate-edit" data-action="edit-address" data-side="${s}" aria-label="Изменить адрес ${sideLabel(s)}">⋯</button></div>`:`<button class="candidate-empty" data-action="search-address" data-side="${s}"><span class="empty-badge">+</span>${s==='a'?'Найти первый адрес':'Добавить адрес Б для сравнения'}</button>`;}
function goalList(){return selectedGoals().map((g,i)=>`<div class="goal-item">${goalBadge(i)}<button class="goal-text" data-action="edit-goal" data-goal="${g.id}" aria-label="Изменить цель ${escapeHTML(g.label)}"><strong>${escapeHTML(g.label)}</strong><small>${escapeHTML(g.address)}</small></button><button class="remove" data-action="remove-goal" data-goal="${g.id}" aria-label="Удалить цель ${escapeHTML(g.label)}">×</button></div>`).join('');}
function tripSetup(){const goals=selectedGoals();const canRun=selectedSides().some(s=>s==='s'||state.profiles[s]==='ready')&&!!goals.length;const busy=Object.values(selectedTrips()).some(t=>t.status==='loading');return `<div class="trip-setup ${!state.mobileSetup&&goals.length?'compact':''}"><div class="step-heading"><span class="step-number">02</span> Куда вы ездите <small>${goals.length} / 3</small></div>${goals.length?`<button class="trip-editor-toggle" data-action="toggle-trip-setup" aria-expanded="${state.mobileSetup}"><span>${goals.length} ${goals.length===1?'цель':'цели'} · ${state.mode==='walking'?'Пешком':'Авто'}</span><span>${state.mobileSetup?'Готово ↑':'Изменить ↓'}</span></button>`:''}<div class="trip-fields">${!goals.length?`<p class="helper">Добавьте важные места. ${state.scenario==='places'?'Для А и Б цели будут общими.':'Каждая поездка рассчитывается от одного старта.'}</p>`:''}<div class="goal-list">${goalList()}</div>${goals.length<3?'<button class="add-goal" data-action="add-goal">＋ Добавить цель поездки</button>':''}${modeSwitch()}</div></div><div class="run-controls"><button class="primary full" data-action="calculate" ${!canRun||busy?'disabled':''}>${busy?'<span class="loader"></span> Считаем поездки…':`Рассчитать ${state.scenario==='standalone'?'поездки':'и сравнить'} <span aria-hidden="true">→</span>`}</button><p class="run-note">${state.mode==='walking'?'Пешком — только между выбранными улицами. Подходы от объектов неизвестны.':'Автомобильная модель без пробок, парковки и подтверждённых подъездов.'}</p></div>`;}
function renderSetup(){
  $('.sidebar').classList.toggle('filled',!!state.a||!!state.b||state.scenario!=='places');
  let html='';
  if(state.scenario==='places')html=`<div class="step-heading"><span class="step-number">01</span> Ваши адреса <small>до двух</small></div>${candidate('a')}${candidate('b')}<div class="radius-setting"><span>Общий радиус анализа</span><div class="seg" role="group" aria-label="Радиус анализа">${[300,500].map(r=>`<button data-action="radius" data-value="${r}" class="${state.radius===r?'selected':''}" aria-pressed="${state.radius===r}">${r} м</button>`).join('')}</div></div><hr class="section-line">${tripSetup()}`;
  if(state.scenario==='standalone')html=`<div class="step-heading"><span class="step-number">01</span> Откуда отправляемся</div><p class="helper">Отдельный сценарий. Адреса А/Б и их цели сохранятся.</p>${state.start?`<div class="candidate"><button class="candidate-main" data-action="pick-start"><span class="badge goal">С</span><span class="candidate-copy"><strong>${escapeHTML(state.start.address)}</strong><small>Произвольный старт · не вход</small></span></button><button class="candidate-edit" data-action="pick-start" aria-label="Изменить старт">⋯</button></div>`:'<button class="candidate-empty" data-action="pick-start"><span class="empty-badge">⌖</span> Выбрать старт на карте</button>'}<button class="text-button" data-action="search-start">Или выбрать адресный объект →</button><hr class="section-line">${tripSetup()}`;
  if(state.scenario==='point')html=`<div class="step-heading"><span class="step-number">01</span> Остановки вокруг точки</div><p class="helper">Укажите любое место на карте. Точка не получает адресный профиль.</p><button class="candidate-empty" data-action="pick-point"><span class="empty-badge">⌖</span>${state.point?'Изменить точку на карте':'Выбрать точку на карте'}</button>${state.point?'<p class="helper">Выбрана произвольная точка.<br>Адрес не назначен.</p>':''}<div class="radius-setting"><span>Общий радиус</span><div class="seg" role="group" aria-label="Радиус анализа">${[300,500].map(r=>`<button data-action="radius" data-value="${r}" class="${state.radius===r?'selected':''}">${r} м</button>`).join('')}</div></div><button class="primary full" data-action="point-calculate" ${!state.point?'disabled':''}>Показать остановки <span aria-hidden="true">→</span></button><p class="run-note">Официальные остановки. Расстояния по прямой, без проверки подходов.</p>`;
  $('#setup').innerHTML=html;
  document.querySelectorAll('[data-action="scenario"]').forEach(b=>{b.classList.toggle('selected',b.dataset.value===state.scenario);b.setAttribute('aria-pressed',b.dataset.value===state.scenario);});
}
function renderMap(){
  const showPlaces=state.scenario==='places';
  $('#radius-a').style.display=showPlaces&&state.a?'':'none';$('#radius-b').style.display=showPlaces&&state.b?'':'none';
  ['a','b'].forEach(s=>{const el=$(`#radius-${s}`);const h=state[s];if(h){el.setAttribute('cx',h.x*10);el.setAttribute('cy',h.y*3.7);}el.setAttribute('r',state.radius===500?103:65);});
  const marker=(h,s)=>`<button class="marker ${s==='b'?'b':''} ${state.active===s?'active':''}" style="left:${h.x}%;top:${h.y}%" data-action="map-side" data-side="${s}" aria-label="На карте: адрес ${sideLabel(s)}, ${escapeHTML(h.address)}">${badge(s)}<span class="marker-label">${escapeHTML(h.address)}</span></button>`;
  let html=showPlaces?['a','b'].filter(s=>state[s]).map(s=>marker(state[s],s)).join(''):state.scenario==='standalone'&&state.start?`<button class="marker" style="left:${state.start.x}%;top:${state.start.y}%" data-action="pick-start" aria-label="Старт на карте"><span class="badge goal">С</span><span class="marker-label">Старт</span></button>`:'';
  if(state.scenario!=='point')html+=selectedGoals().map((g,i)=>`<button class="marker" style="left:${g.x}%;top:${g.y}%" data-action="map-goal" data-goal="${g.id}" aria-label="На карте: цель ${escapeHTML(g.label)}">${goalBadge(i)}<span class="marker-label">${escapeHTML(g.label)}</span></button>`).join('');
  if(state.scenario==='point'&&state.point)html+=`<span class="point-spot" style="left:${state.point.x}%;top:${state.point.y}%" role="img" aria-label="Выбранная произвольная точка"></span>`;
  $('#map-markers').innerHTML=html;
  const entry=state.selectedTrip&&selectedTrips()[state.selectedTrip];
  $('#route-lines').style.display=entry?.status==='available'?'':'none';
  if(entry?.status==='available'){const h=getHouse(entry.side),g=selectedGoals().find(g=>g.id===entry.goal);const sx=h.x*10+13,sy=h.y*3.7+12,tx=g.x*10+8,ty=g.y*3.7-10;const d=`M${sx} ${sy} L${sx+55} ${sy-12} L${sx+75} ${ty-20} L${tx} ${ty}`;const color=entry.side==='b'?'#bd734f':'#7560bd';$('#route-lines').innerHTML=`<path d="${d}" stroke="white" stroke-width="9"/><path d="${d}" stroke="${color}" stroke-width="4"/><circle cx="${sx}" cy="${sy}" r="5" fill="white" stroke="${color}" stroke-width="3"/><circle cx="${tx}" cy="${ty}" r="5" fill="white" stroke="${color}" stroke-width="3"/>`;}
  $('#route-lines').style.opacity=state.selectedTrip?.startsWith('b:')?'.85':'1';
  $('#map-context').textContent=state.pick?({point:'Выберите точку для остановок',start:'Выберите произвольный старт',goal:'Выберите точку цели',street:'Выберите уличную точку'}[state.pick.kind]):entry?.status==='available'?`${state.mode==='walking'?'Пешая уличная часть':'Автомодель без пробок'} · ${sideLabel(entry.side)} → ${selectedGoals().find(g=>g.id===entry.goal)?.label||'цель'}`:state.scenario==='point'?'Остановки вокруг точки':state[ state.active ]&&showPlaces?`Адрес ${sideLabel(state.active)} · радиус ${state.radius} м`:'Центр Красноярска';
  $('.map-section').classList.toggle('point-picker',!!state.pick);
  $('#map-art').style.transform=state.mapZoom?'scale(1.15)':'none';
  if(state.pick){$('#map-callout').hidden=false;$('#map-callout').innerHTML=`<button class="close-callout icon-button" data-action="cancel-pick" aria-label="Отменить выбор точки">×</button><span class="tag">ВЫБОР НА СХЕМЕ</span><h3>${state.pick.kind==='street'?'Новая уличная точка':'Нажмите на карту'}</h3><p>${state.pick.kind==='street'?'Исходный объект сохранится. Подход к улице не проверяется.':'Нажмите на свободное место. Для клавиатуры доступна кнопка выбора демонстрационной точки.'}</p><button class="primary full" data-action="confirm-map-point">Выбрать демо-точку здесь</button>`;}
  else $('#map-callout').hidden=true;
}
function emptyResult(){return `<div class="empty-state"><div class="empty-icon" aria-hidden="true">⌖</div><h3>У каждого адреса —<br>своя повседневность</h3><p>Найдите первый адрес. Посмотрите окружение, добавьте второй вариант и сравните поездки к важным для вас местам.</p><div class="empty-actions"><button class="primary" data-action="search-address" data-side="a">Найти адрес <span aria-hidden="true">→</span></button><button class="quiet" data-action="demo">Попробовать на примере</button></div><div class="empty-steps"><span><i>01</i> Выберите адрес</span><span><i>02</i> Добавьте цели</span><span><i>03</i> Сравните факты</span></div></div>`;}
function columns(sides){return sides.map(s=>`<th scope="col"><div class="column-title">${s==='s'?'<span class="badge goal">С</span>':badge(s)}<span>${s==='s'?'От старта':`Адрес ${sideLabel(s)}`}<small>${escapeHTML(getHouse(s)?.address)}</small></span></div></th>`).join('');}
const metrics=[
  {id:'stops',name:'Ближайшая остановка',caption:'По прямой',a:140,b:290,unit:'м',noteA:'Театральная площадь',noteB:'Улица Ленина',method:'Расстояние от адресного объекта до точки остановки. Доступность переходов и фактический подход не проверены.',source:'Демо официального набора остановок',map:'stops-layer'},
  {id:'count',name:'Остановки в радиусе',caption:'Официальный набор',a:6,b:9,unit:'шт.',noteA:'В круге анализа',noteB:'В круге анализа',method:'Число отдельных точек официальных остановок в общем радиусе. Направления движения не объединены; частота транспорта неизвестна.',source:'Демо официального набора остановок',map:'stops-layer'},
  {id:'park',name:'Ближайший парк',caption:'До границы · по прямой',a:230,b:610,unit:'м',noteA:'В пределах радиуса',noteB:'За радиусом 500 м',method:'Минимальное прямое расстояние до границы территории. Ближайшая точка границы не является входом. У адреса Б объект за кругом анализа, но внутри демонстрационного охвата.',source:'Демо локального OSM-снимка · парки',map:'park-layer'},
  {id:'green',name:'Растительная территория',caption:'Доля в круге · независимо от парков',a:18,b:null,unit:'%',noteA:'По картографическому набору',noteB:'Неполное покрытие снимка',method:'Доля объединённых растительных территорий в круге. Пересечения не складываются. Растительность и парк — независимые признаки; по адресу Б покрытие недостаточно, значение неизвестно.',source:'Демо локального OSM-снимка · растительность',map:'park-layer'},
  {id:'road',name:'Крупная дорога',caption:'До линии · по прямой',a:85,b:210,unit:'м',noteA:'Шум не измерен',noteB:'Шум не измерен',method:'Минимальное расстояние до линии крупной дороги. Оно не измеряет шум, интенсивность движения или загрязнение.',source:'Демо локального OSM-снимка · дороги'},
  {id:'water',name:'Вода',caption:'До границы · по прямой',a:370,b:520,unit:'м',noteA:'Доступ к берегу неизвестен',noteB:'Доступ к берегу неизвестен',method:'Прямое расстояние до границы воды. Наличие прохода к берегу и его безопасность не установлены.',source:'Демо локального OSM-снимка · вода'},
  {id:'rail',name:'Железная дорога',caption:'До линии · по прямой',a:1800,b:1450,unit:'м',noteA:'Вне радиуса анализа',noteB:'Вне радиуса анализа',method:'Ближайшая линия в подтверждённом охвате демонстрационного набора. За радиусом анализа. Расписание, фактическое движение и шум неизвестны.',source:'Демо локального OSM-снимка · железная дорога'}
];
function metricValue(m,s){
  if(state.profiles[s]==='loading')return '<div class="skeleton"></div><div class="skeleton short"></div>';
  if(state.profiles[s]==='error')return `<span class="metric-value unknown">Недоступно</span><span class="metric-note">Профиль не загружен</span>`;
  let v=m[s];if(m.id==='count'&&state.radius===300)v=s==='a'?3:5;if(m.id==='green'&&state.radius===300&&s==='a')v=12;
  const h=state[s];if(h&&h.id!=='demo-house-1'&&h.id!=='demo-house-2'&&v!=null&&m.unit==='м')v+=70;
  return v===null?`<strong class="metric-value unknown">Нет данных</strong><span class="metric-note">${m.noteB}</span>`:`<strong class="metric-value value-${s}">${v>=1000?(v/1000).toLocaleString('ru-RU',{maximumFractionDigits:2}):v}<small>${v>=1000?'км':m.unit}</small></strong><span class="metric-note">${m.id==='park'&&v>state.radius?`За радиусом ${state.radius} м`:m[s=== 'a'?'noteA':'noteB']}</span>`;
}
function overview(){
  const sides=selectedSides();const both=sides.length===2;const loading=sides.some(s=>state.profiles[s]==='loading');
  return `${sides.filter(s=>state.profiles[s]==='error').map(s=>`<div class="notice"><span>ⓘ</span><p>Профиль ${sideLabel(s)} не загрузился. Независимые результаты другой стороны доступны.</p><button class="text-button" data-action="retry-profile" data-side="${s}">Повторить ${sideLabel(s)}</button></div>`).join('')}${!both?`<div class="profile-next"><div><strong>Это профиль одного адреса</strong><p>Добавьте второй, чтобы увидеть те же показатели рядом.</p></div><button class="quiet" data-action="search-address" data-side="${state.a?'b':'a'}">＋ Добавить адрес ${state.a?'Б':'А'}</button></div>`:''}${both&&!loading&&state.profiles.a==='ready'&&state.profiles.b==='ready'?`<div class="insights"><div class="insight"><span class="insight-icon" aria-hidden="true">↔</span><p><strong>У А остановка на ${150+(state.b?.id!=='demo-house-1'&&state.b?.id!=='demo-house-2'?70:0)-(state.a?.id!=='demo-house-1'&&state.a?.id!=='demo-house-2'?70:0)} м ближе</strong><small>По прямой. Подход ещё нужно проверить.</small></p></div><div class="insight"><span class="insight-icon" aria-hidden="true">◌</span><p><strong>По растительности Б нет данных</strong><small>Неполное покрытие — это неизвестность.</small></p></div></div>`:''}<table class="metric-table"><caption class="sr-only">Окружение адресов в радиусе ${state.radius} метров</caption><thead><tr><th scope="col">Окружение <span class="metric-caption">· ${state.radius} м</span></th>${columns(sides)}</tr></thead><tbody>${metrics.map(m=>`<tr class="${state.detail===m.id?'selected-row':''}"><td><button class="metric-name" data-action="metric" data-metric="${m.id}" aria-expanded="${state.detail===m.id}">${m.name}<span aria-hidden="true">${state.detail===m.id?'−':'↗'}</span></button><div class="metric-caption">${m.caption}</div></td>${sides.map(s=>`<td>${metricValue(m,s)}</td>`).join('')}</tr>${state.detail===m.id?`<tr class="metric-detail"><td colspan="${sides.length+1}"><div class="detail-grid"><div><strong>Что означает показатель</strong>${m.method}</div><div><strong>Происхождение и актуальность</strong>${m.source}. Снимок demo-2026-10. Дата наблюдения неизвестна. ${m.id==='green'?'Покрытие А: полное в демо; Б: неполное.':'Покрытие обеих сторон: полное в демо.'}<br><button class="text-button" data-action="sources">Подробнее об источниках ↗</button>${m.map?` · <button class="text-button" data-action="metric-map" data-layer="${m.map}">Показать на карте ↗</button>`:''}</div></div></td></tr>`:''}`).join('')}</tbody></table><p class="metric-footnote">Расстояния по прямой не описывают пеший путь. Близость парка не подтверждает вход, близость дороги — уровень шума. Дата наблюдения данных неизвестна.</p>`;
}
function tripEntry(g,s,i){const key=`${s}:${g.id}`;const t=selectedTrips()[key];if(!t)return `<td class="trip-cell"><span class="unknown">Не рассчитано</span><button class="text-button" data-action="retry-trip" data-key="${key}">Рассчитать поездку</button></td>`;
  if(t.status==='loading')return `<td class="trip-cell"><span class="inline-state"><span class="loader"></span> Считаем…</span><div class="metric-note">Другие результаты доступны</div></td>`;
  if(t.status==='error')return `<td class="trip-cell trip-error"><span class="trip-status">Не удалось рассчитать</span><div class="metric-note">Маршрутизатор не ответил</div><button class="text-button" data-action="retry-trip" data-key="${key}">Повторить только ${sideLabel(s)}</button></td>`;
  if(t.status==='refine')return `<td class="trip-cell trip-error"><span class="trip-status">Нужна уличная точка</span><span class="metric-note">${state.refined[key+':start']?'Нужна улица цели.':'Нужна улица старта.'}<br>Длина и время неизвестны.</span><button class="text-button" data-action="refine" data-key="${key}" data-end="${state.refined[key+':start']?'target':'start'}">Уточнить улицу →</button></td>`;
  return `<td class="trip-cell ${state.selectedTrip===key?'selected':''}"><strong class="metric-value value-${s==='b'?'b':'a'}">${t.km.toLocaleString('ru-RU',{minimumFractionDigits:1})}<small>км</small></strong><div class="trip-meta">≈ ${t.minutes} мин <span class="sr-only">по модели</span></div><span class="metric-note">${state.mode==='walking'?'Уличная часть':'Без пробок'}</span><button class="text-button" data-action="show-route" data-key="${key}">На карте ↗</button><button class="text-button" data-action="trip-detail" data-key="${key}">Детали и уточнение</button></td>`;
}
function tripsView(){const sides=selectedSides(),goals=selectedGoals();if(!goals.length)return `<div class="empty-state"><div class="empty-icon">↗</div><h3>Добавьте важные места</h3><p>Работа, учёба или спорт. До трёх целей с одним режимом поездки ${state.scenario==='places'?'для обоих адресов':''}.</p><button class="primary" data-action="add-goal" style="margin:auto">＋ Добавить первую цель</button></div>`;
  const key=state.selectedTrip;const t=selectedTrips()[key];const goal=t&&goals.find(g=>g.id===t.goal);
  return `<div class="notice neutral"><span aria-hidden="true">ⓘ</span><p>${state.mode==='walking'?'<strong>Сравнивается только уличная часть.</strong> Подходы от адресов и цели к выбранным улицам неизвестны. Время — оценка модели.':'<strong>Автомобильная модель без пробок.</strong> Время не учитывает парковку, подходы и реальное движение в городе.'}</p></div><table class="metric-table trip-table"><caption class="sr-only">Поездки к общим целям, режим ${state.mode==='walking'?'пешком':'авто'}</caption><thead><tr><th scope="col">${state.scenario==='places'?'Общие цели':'Цели поездок'}<small class="metric-note">${state.mode==='walking'?'Пешком · уличная часть':'Авто · модель'}</small></th>${columns(sides)}</tr></thead><tbody>${goals.map((g,i)=>`<tr><td><div class="trip-goal-title">${goalBadge(i)}${escapeHTML(g.label)}</div><span class="trip-goal-address">${escapeHTML(g.address)}</span></td>${sides.map(s=>tripEntry(g,s,i)).join('')}</tr>`).join('')}</tbody></table>${!Object.keys(selectedTrips()).length?'<p class="metric-footnote">Параметры готовы. Нажмите «Рассчитать и сравнить» в панели настройки. Расчёт запускается явно.</p>':''}${t&&goal?`<div class="trip-detail"><div class="result-heading"><h4>${sideLabel(t.side)} → ${escapeHTML(goal.label)}</h4><button class="text-button" data-action="close-trip-detail">Закрыть</button></div><p>${t.status==='available'?`Длина ${t.km.toLocaleString('ru-RU')} км относится ${state.mode==='walking'?'к выбранным уличным точкам':'к автомобильной дорожной модели'}. Модельное время ≈ ${t.minutes} мин. `:''}Подходы от исходных объектов не подтверждены. Точка контура здания не является входом.</p><div class="endpoints"><div class="endpoint"><b>Исходный объект / старт</b>${escapeHTML(getHouse(t.side)?.address)}<br><span class="metric-note">${state.refined[key+':start']?'Уличная точка выбрана явно':'Уличная точка в демо · не вход'}</span><button class="text-button" data-action="refine" data-key="${key}" data-end="start">Уточнить улицу старта →</button></div><div class="endpoint"><b>Исходная цель</b>${escapeHTML(goal.address)}<br><span class="metric-note">${state.refined[key+':target']?'Уличная точка выбрана явно':'Улица ещё не выбрана'}</span><button class="text-button" data-action="refine" data-key="${key}" data-end="target">Уточнить улицу цели →</button></div></div><button class="text-button" data-action="retry-trip" data-key="${key}">↻ Повторить только эту поездку</button> · <button class="text-button" data-action="sources">Метод и снимок ↗</button></div>`:''}<div class="trip-controls"><button class="quiet" data-action="calculate">↻ Пересчитать поездки</button><button class="text-button" data-action="clear-results">Очистить результаты поездок</button></div><p class="metric-footnote">Сбой одной поездки не отменяет остальные. Уточнение перепроверяет только выбранную ячейку. Все числа — синтетическая демонстрация.</p>`;
}
function dataView(){return `<div class="notice neutral"><span>ⓘ</span><p>В этом макете нет настоящих наблюдений. Имена источников показывают структуру будущих сведений, а не подтверждают актуальность данных.</p></div><div class="data-grid">${selectedSides().map(s=>`<article class="data-card"><h4>${sideLabel(s)} · ${escapeHTML(getHouse(s)?.address)}</h4><dl><dt>Объект</dt><dd>${escapeHTML(getHouse(s)?.id||'Произвольная точка')}</dd><dt>Набор окружения</dt><dd>demo-osm-2026-10</dd><dt>Остановки</dt><dd>demo-official-stops</dd><dt>Дата наблюдения</dt><dd>Неизвестна</dd><dt>Покрытие</dt><dd>${s==='b'?'Растительность: неполное. Остальное: полное в демо.':'Полное в демо'}</dd><dt>Доступность</dt><dd>${state.profiles[s]==='error'?'Профиль недоступен':'По отдельным блокам'}</dd></dl><button class="text-button" data-action="sources">Методы и ограничения ↗</button></article>`).join('')}</div><p class="metric-footnote">Одинаковая дата версии не гарантирует одинаковую дату наблюдения. Метод, доступность и актуальность показываются отдельно.</p>`;}
function pointView(){if(!state.point)return `<div class="empty-state"><div class="empty-icon">⌖</div><h3>Любая точка. Остановки рядом.</h3><p>Выберите место на схеме. Здесь доступен анализ официальных остановок, без назначения адресного профиля.</p><button class="primary" style="margin:auto" data-action="pick-point">Выбрать точку на карте →</button></div>`;if(state.pointReady==='loading')return '<div class="point-result" role="status"><span class="loader"></span> Ищем остановки в демонстрационном радиусе…</div>';if(!state.pointReady)return '<div class="point-result"><h3>Точка выбрана</h3><p class="helper">Нажмите «Показать остановки» для расчёта.</p><button class="primary" data-action="point-calculate">Показать остановки →</button></div>';return `<div class="point-result"><div class="result-heading"><h3>Остановки в ${state.radius} м</h3><small>Точка без адреса</small></div><p class="helper">${state.radius===500?'4':'2'} демонстрационные остановки. Расстояния по прямой.</p>${[{n:'Театральная площадь',d:120},{n:'Улица Сурикова',d:240},{n:'Дом техники',d:360},{n:'Улица Ленина',d:470}].filter(s=>s.d<=state.radius).map(s=>`<div class="stop-row"><div><strong>${s.n}</strong><small>Официальный набор · демо</small></div><span>${s.d} м</span></div>`).join('')}<div class="notice neutral"><span>ⓘ</span><p>Переходы и подходы не проверены. Дата наблюдения неизвестна. Точка не считается адресным объектом.</p></div><button class="text-button" data-action="sources">Источник и покрытие ↗</button></div>`;}
function renderResults(){
  const has=!!selectedSides().length;
  $('#workspace-title').textContent=state.scenario==='point'?'Остановки рядом':state.scenario==='standalone'?'Отдельная поездка':state.a&&state.b?'Два адреса. Одна повседневность.':state.a||state.b?'Знакомимся с адресом':'Начнём с одного адреса';
  $('#workspace-kicker').textContent=state.scenario==='places'?'ОТ АДРЕСА К ПОНИМАНИЮ МЕСТА':state.scenario==='point'?'ПРОИЗВОЛЬНАЯ ТОЧКА · БЕЗ АДРЕСНОГО ПРОФИЛЯ':'СВОЙ СТАРТ · ОТДЕЛЬНЫЕ ЦЕЛИ';
  let html='';
  if(state.scenario==='point')html=pointView();
  else if(!has)html=state.scenario==='standalone'?`<div class="empty-state"><div class="empty-icon">↗</div><h3>Ваша поездка начинается здесь</h3><p>Выберите произвольный старт и до трёх целей. Это отдельный сценарий: сравнение А/Б сохранится.</p><button class="primary" style="margin:auto" data-action="pick-start">Выбрать старт →</button></div>`:emptyResult();
  else html=`<div class="result-heading"><h3>${state.scenario==='standalone'?'Поездки от вашего старта':state.a&&state.b?'Сравнение вариантов':'Профиль адреса'}</h3><small>${state.scenario==='places'?`${state.radius} м · одинаковые условия`:'Самостоятельный сценарий'}</small></div><div class="result-tabs" role="group" aria-label="Раздел результатов">${(state.scenario==='places'?[['overview','Окружение'],['trips','Поездки'],['data','Данные']]:[['trips','Поездки'],['data','Данные']]).map(([id,name])=>`<button data-action="tab" data-value="${id}" class="${state.tab===id?'selected':''}" aria-pressed="${state.tab===id}">${name}${id==='trips'&&selectedGoals().length?`<span class="count-badge">${selectedGoals().length}</span>`:''}</button>`).join('')}<button class="collapse" data-action="collapse" aria-expanded="${!state.collapsed}">${state.collapsed?'Развернуть ↓':'Свернуть ↑'}</button></div>${state.collapsed?'<button class="quiet" data-action="collapse">Развернуть результаты ↓</button>':state.tab==='overview'?overview():state.tab==='trips'?tripsView():dataView()}`;
  $('#result-content').innerHTML=html;
  $('#main').classList.toggle('map-view',state.view==='map');
  document.querySelectorAll('[data-action="view"]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===state.view));
}
function render(){const focus=document.activeElement;const action=focus?.dataset?.action;const key=focus?.dataset?.key;renderSetup();renderMap();renderResults();if(action&&!dialog.open){const matches=[...document.querySelectorAll(`[data-action="${action}"]`)];const next=matches.find(e=>key?e.dataset.key===key:e.dataset.side===focus.dataset.side&&e.dataset.value===focus.dataset.value&&e.dataset.goal===focus.dataset.goal);if(next)next.focus({preventScroll:true});}}
function focusResults(){state.view='results';renderResults();$('#results').scrollIntoView({behavior:'smooth',block:'start'});$('#results').focus({preventScroll:true});}
function openSearch(kind='address',side='a',replaceGoal=null){
  const goalMode=kind==='goal';const title=goalMode?'Куда вы ездите?':kind==='start'?'Выберите объект старта':`Выберите адрес ${sideLabel(side)}`;
  openDialog(title,'Красноярск · демонстрационный каталог конкретных объектов',`<div class="search-field"><span aria-hidden="true">⌕</span><input id="search" aria-label="${goalMode?'Поиск цели':'Поиск адреса'}" placeholder="${goalMode?'Место или адрес':'Например, проспект Мира, 10'}" autocomplete="off"></div><div id="search-list"></div><p class="metric-footnote">Выбор подтверждается нажатием на конкретный объект. В каталоге только синтетические демо-объекты.</p>`,goalMode?`<button class="quiet" data-action="goal-map" ${replaceGoal?`data-replace="${replaceGoal}"`:''}>⌖ Выбрать точку на карте</button>`:'');
  const items=goalMode?destinations:houses;
  const draw=()=>{const q=$('#search').value.toLocaleLowerCase('ru').trim();const found=items.filter(h=>(h.address+' '+(h.label||'')).toLocaleLowerCase('ru').includes(q));$('#search-list').innerHTML=found.length?found.map(h=>`<button class="search-result" data-action="choose-search" data-kind="${kind}" data-id="${h.id}" data-side="${side}" ${replaceGoal?`data-replace="${replaceGoal}"`:''}><span class="object-icon" aria-hidden="true">${goalMode?'⌖':'▥'}</span><span>${escapeHTML(h.label||h.address)}<small>${escapeHTML(goalMode?h.address+' · конкретный демо-объект':h.type)}</small></span><span style="flex:none;color:#a19aa9" aria-hidden="true">↗</span></button>`).join(''):'<p class="search-empty">В демо-каталоге совпадений нет. Попробуйте «Мира», «Ленина» или выберите доступный объект.</p>';};
  draw();$('#search').addEventListener('input',draw);$('#search').addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();$('#search-list button')?.focus();}if(e.key==='Enter'){$('#search-list button')?.click();}});$('#search').focus();
}
function invalidateSide(s){Object.keys(state.trips).filter(k=>k.startsWith(s+':')).forEach(k=>delete state.trips[k]);Object.keys(state.refined).filter(k=>k.startsWith(s+':')).forEach(k=>delete state.refined[k]);if(state.selectedTrip?.startsWith(s+':'))state.selectedTrip=null;}
function loadProfile(s){const token=++state.profileRuns[s];state.profiles[s]='loading';render();setTimeout(()=>{if(token!==state.profileRuns[s]||!state[s])return;state.profiles[s]='ready';render();announce(`Профиль ${sideLabel(s)} готов`);},800);}
function chooseAddress(h,s){state[s]={...h};state.active=s;invalidateSide(s);state.scenario='places';state.view='results';state.tab='overview';state.collapsed=false;closeDialog();loadProfile(s);$(`[data-action="select-side"][data-side="${s}"]`).focus({preventScroll:true});}
function calculateOne(key,fail=false,force=false){
  const [s,gid]=key.split(':');const scenario=state.scenario;const records=selectedTrips();const goal=selectedGoals().find(g=>g.id===gid);if(!goal||!getHouse(s))return;if(s!=='s'&&state.profiles[s]!=='ready'){toast(`Сначала дождитесь профиля ${sideLabel(s)} или повторите его загрузку.`);return;}
  const token=Symbol(key);records[key]={status:'loading',side:s,goal:gid,token};render();
  setTimeout(()=>{if(records[key]?.token!==token||records!==(scenario==='standalone'?state.standaloneTrips:state.trips))return;const i=(scenario==='standalone'?state.standaloneGoals:state.goals).findIndex(g=>g.id===gid);const refine=state.mode==='walking'&&(!state.refined[key+':start']||!state.refined[key+':target']);
    const km=state.mode==='walking'?(i===0?(s==='b'?1.8:1.2):(s==='b'?1.1:2.3)):(i===0?(s==='b'?2.8:2.1):(s==='b'?2.2:3.6));
    records[key]={status:fail?'error':refine?'refine':'available',side:s,goal:gid,km,minutes:state.mode==='walking'?Math.round(km*13):Math.round(km*3+2)};
    render();announce(`${sideLabel(s)} → ${goal.label}: ${fail?'ошибка, доступен повтор':refine?'нужно уточнить уличную точку':'результат готов'}`);
  },950+Math.random()*450);
}
function calculate(){if(!selectedSides().length||!selectedGoals().length){toast('Сначала выберите старт и хотя бы одну цель.');return;}state.tab='trips';state.collapsed=false;state.selectedTrip=null;const keys=selectedSides().flatMap(s=>selectedGoals().map(g=>`${s}:${g.id}`));keys.forEach((k,i)=>calculateOne(k,state.failNext&&i===keys.length-1));state.failNext=false;focusResults();}
function demo(type='filled'){
  state.profileRuns.a++;state.profileRuns.b++;state.pointRun++;state.a={...houses[0]};state.b={...houses[1]};state.active='a';state.scenario='places';state.radius=500;state.mode='walking';state.tab=type==='partial'?'trips':'overview';state.view='results';state.mobileSetup=false;state.goals=[{...destinations[0]},{...destinations[2]}];state.profiles={a:'ready',b:'ready'};state.trips={};state.refined={};state.goals.forEach(g=>{['a','b'].forEach(side=>{state.refined[`${side}:${g.id}:target`]=true;if(side==='a'||g.id!=='demo-goal-work')state.refined[`${side}:${g.id}:start`]=true;});});state.pick=null;state.selectedTrip=null;state.collapsed=false;
  ['a','b'].forEach(s=>state.goals.forEach((g,i)=>{const km=i===0?(s==='a'?1.2:1.8):(s==='a'?2.3:1.1);state.trips[`${s}:${g.id}`]={side:s,goal:g.id,status:type==='partial'&&s==='b'&&i===1?'error':s==='b'&&i===0?'refine':'available',km,minutes:Math.round(km*13)};}));
  if(type==='loading'){state.tab='trips';state.trips={};render();calculate();return;}
  render();announce('Загружен демонстрационный пример двух адресов');
}
function reset(){state.profileRuns.a++;state.profileRuns.b++;state.pointRun++;Object.assign(state,{scenario:'places',a:null,b:null,active:'a',goals:[],standaloneGoals:[],start:null,point:null,pointReady:false,trips:{},standaloneTrips:{},profiles:{a:'empty',b:'empty'},tab:'overview',view:'results',selectedTrip:null,detail:null,refined:{},pick:null,collapsed:false});render();$('#main').scrollTop=0;window.scrollTo(0,0);}
function sources(){openDialog('Факты, методы и неизвестность','Прозрачность важнее одного итогового балла',`<span class="tag">ВСЕ ЗНАЧЕНИЯ В МАКЕТЕ — ДЕМО</span><p>Окружение и поездки показаны на синтетических данных. Прототип ничего не запрашивает у реальных аналитических сервисов.</p><h3>Окружение</h3><dl class="source-dl"><dt>Остановки</dt><dd>Демо официального набора. Не подмешаны из OSM.</dd><dt>Парки, вода, растительность, дороги</dt><dd>Демо локального OSM-снимка.</dd><dt>Версия набора</dt><dd>demo-2026-10</dd><dt>Дата наблюдения</dt><dd>Неизвестна для обеих сторон.</dd><dt>Покрытие</dt><dd>У Б неполное по растительности. Остальное полное только в рамках демо.</dd><dt>Расстояния</dt><dd>По прямой до точки, границы или линии. Это не маршрут.</dd></dl><h3>Поездки</h3><p>Пешком — между выбранными уличными точками. Подходы от исходных объектов и входы неизвестны. Авто — статическая дорожная модель без пробок и парковки. Время относится к модели и не является обещанием обычной городской поездки.</p><h3>Как читать пропуски</h3><p>«Нет данных» означает неизвестное значение, а не ноль и не недостаток места. Ошибка маршрута не говорит, что путь невозможен. Доступность, метод и актуальность — разные свойства.</p><div class="notice neutral"><p>Парк рядом не доказывает открытый вход. Дорога рядом не измеряет шум. Наложенные площади не складываются. Общего рейтинга и победителя нет.</p></div>`);}
function refine(key,end='start'){
  const [s,gid]=key.split(':');const g=selectedGoals().find(g=>g.id===gid);if(!g)return;
  openDialog(`Уточнить улицу ${end==='start'?'старта':'цели'}`,`${sideLabel(s)} → ${escapeHTML(g.label)} · исходные объекты сохранятся`,`<p>Выберите уличную точку для проверки пути. Смещение от проверяемой точки не является длиной подхода от здания.</p><button class="choice" data-action="choose-street" data-key="${key}" data-end="${end}" data-street="1"><strong>① Улица Вейнбаума</strong><small>12 м от проверяемой точки · ${state.mode==='walking'?'пешеходный':'дорожный'} сегмент</small></button><button class="choice" data-action="choose-street" data-key="${key}" data-end="${end}" data-street="2"><strong>② Улица Ленина</strong><small>18 м от проверяемой точки · ${state.mode==='walking'?'пешеходный':'дорожный'} сегмент</small></button><div class="notice neutral"><p>Это синтетические варианты. Выбор запускает повтор только этой поездки. Подходы к объектам остаются неизвестными.</p></div>`,`<button class="quiet" data-action="street-map" data-key="${key}" data-end="${end}">⌖ Другая точка на карте</button>`);
}
function beginPick(kind,extra={}){if(dialog.open)closeDialog();state.pick={kind,...extra};state.view='map';render();$('.map-section').scrollIntoView({behavior:'smooth',block:'start'});$('#map-callout button.primary').focus({preventScroll:true});}
function confirmPick(x=48,y=46){const p=state.pick;if(!p)return;state.pick=null;if(p.kind==='point'){state.point={x,y};state.pointReady=false;}if(p.kind==='start'){state.start={address:'Произвольная точка на карте',x,y};state.standaloneTrips={};}if(p.kind==='goal'){const id='demo-map-goal-'+Date.now();const goal={id,label:'Место на карте',address:'Произвольная точка · без адреса',x,y};if(p.replace){const ix=selectedGoals().findIndex(g=>g.id===p.replace);if(ix>=0)selectedGoals().splice(ix,1,goal);Object.keys(selectedTrips()).filter(k=>k.endsWith(':'+p.replace)).forEach(k=>delete selectedTrips()[k]);state.selectedTrip=null;}else if(selectedGoals().length<3)selectedGoals().push(goal);}if(p.kind==='street'){state.refined[p.key+':'+p.end]=true;state.selectedTrip=p.key;state.tab='trips';calculateOne(p.key,false,true);toast('Уличная точка выбрана. Перепроверяем эту поездку.');}state.view='results';render();if(p.kind!=='street')toast('Точка выбрана явно. Адрес не назначен.');focusResults();}
document.addEventListener('click',e=>{
  const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
  if(a==='close-dialog'){closeDialog();return;}
  if(a==='demo'){if(dialog.open)closeDialog();demo();$('#main').scrollTop=0;window.scrollTo(0,0);return;}
  if(a==='states'){openDialog('Попробуйте разные состояния','Управление самостоятельным прототипом',`<div class="state-controls"><button class="choice" data-action="state" data-value="empty"><strong>01 · Пустой экран</strong><small>Начать сценарий с нуля</small></button><button class="choice" data-action="state" data-value="filled"><strong>02 · Заполненное сравнение</strong><small>Два адреса и две общие цели</small></button><button class="choice" data-action="state" data-value="loading"><strong>03 · Загрузка</strong><small>Независимые результаты появятся постепенно</small></button><button class="choice" data-action="state" data-value="partial"><strong>04 · Частичный отказ</strong><small>Повтор одной поездки, остальные доступны</small></button></div><p class="metric-footnote">Дополнительно можно воспроизвести отказ профиля одной стороны.</p><button class="quiet" data-action="profile-failure">Показать отказ профиля Б</button>`);return;}
  if(a==='state'){closeDialog();el.dataset.value==='empty'?reset():demo(el.dataset.value);return;}
  if(a==='profile-failure'){closeDialog();demo();state.profiles.b='error';invalidateSide('b');render();return;}
  if(a==='scenario'){state.scenario=el.dataset.value;state.tab=state.scenario==='standalone'?'trips':'overview';state.selectedTrip=null;state.pick=null;state.view='results';state.detail=null;render();return;}
  if(a==='view'){state.view=el.dataset.value;renderResults();return;}
  if(a==='search-address'){openSearch('address',el.dataset.side);return;}
  if(a==='search-start'){openSearch('start');return;}
  if(a==='choose-search'){const kind=el.dataset.kind;if(kind==='address'){chooseAddress(houses.find(h=>h.id===el.dataset.id),el.dataset.side);return;}if(kind==='start'){state.start={...houses.find(h=>h.id===el.dataset.id)};state.standaloneTrips={};closeDialog();render();return;}const g={...destinations.find(g=>g.id===el.dataset.id)};if(selectedGoals().some(x=>x.id===g.id&&x.id!==el.dataset.replace)){toast('Эта цель уже добавлена. Выберите другое место.');return;}if(el.dataset.replace){const ix=selectedGoals().findIndex(g=>g.id===el.dataset.replace);selectedGoals().splice(ix,1,g);Object.keys(selectedTrips()).filter(k=>k.endsWith(':'+el.dataset.replace)).forEach(k=>delete selectedTrips()[k]);}else if(selectedGoals().length<3)selectedGoals().push(g);closeDialog();state.selectedTrip=null;render();return;}
  if(a==='edit-address'){const s=el.dataset.side;openDialog(`Адрес ${sideLabel(s)}`,escapeHTML(state[s].address),`<button class="choice" data-action="replace-address" data-side="${s}"><strong>Заменить адрес</strong><small>Показатели и поездки этой стороны будут пересчитаны</small></button><button class="choice" data-action="remove-address" data-side="${s}"><strong>Убрать из сравнения</strong><small>Другая сторона и её поездки сохранятся</small></button>`);return;}
  if(a==='replace-address'){openSearch('address',el.dataset.side);return;}
  if(a==='remove-address'){const s=el.dataset.side;state.profileRuns[s]++;state[s]=null;state.profiles[s]='empty';invalidateSide(s);if(state.active===s)state.active=state[s==='a'?'b':'a']?(s==='a'?'b':'a'):'a';closeDialog();state.tab='overview';render();return;}
  if(a==='select-side'||a==='map-side'){state.active=el.dataset.side;state.mapZoom=a==='map-side';render();if(a==='map-side')toast(`Выбран адрес ${sideLabel(state.active)}: ${state[state.active].address}`);return;}
  if(a==='radius'){state.radius=Number(el.dataset.value);state.detail=null;if(state.scenario==='point'){state.pointReady=false;state.pointRun++;render();}else{['a','b'].filter(s=>state[s]).forEach(loadProfile);render();}return;}
  if(a==='toggle-trip-setup'){state.mobileSetup=!state.mobileSetup;render();return;}
  if(a==='add-goal'){state.mobileSetup=true;if(selectedGoals().length<3)openSearch('goal');return;}
  if(a==='goal-map'){if(el.dataset.replace||selectedGoals().length<3)beginPick('goal',{replace:el.dataset.replace});return;}
  if(a==='remove-goal'){const g=el.dataset.goal;const goals=selectedGoals();goals.splice(goals.findIndex(x=>x.id===g),1);Object.keys(selectedTrips()).filter(k=>k.endsWith(':'+g)).forEach(k=>delete selectedTrips()[k]);if(state.selectedTrip?.endsWith(':'+g))state.selectedTrip=null;render();return;}
  if(a==='edit-goal'){const g=selectedGoals().find(g=>g.id===el.dataset.goal);openDialog('Важное место',escapeHTML(g.address),`<label class="form-label" for="goal-name">Название цели</label><input class="input" id="goal-name" maxlength="40" value="${escapeHTML(g.label)}"><p class="metric-footnote">Переименование сохраняет рассчитанные поездки.</p><button class="text-button" data-action="replace-goal" data-goal="${g.id}">Выбрать другой объект или точку →</button>`,`<button class="primary" data-action="save-goal-name" data-goal="${g.id}">Сохранить название</button>`);return;}
  if(a==='save-goal-name'){const name=$('#goal-name').value.trim();if(!name){$('#goal-name').focus();toast('Введите название цели.');return;}selectedGoals().find(g=>g.id===el.dataset.goal).label=name;closeDialog();render();return;}
  if(a==='replace-goal'){openSearch('goal','a',el.dataset.goal);return;}
  if(a==='mode'){if(state.mode===el.dataset.value)return;state.mode=el.dataset.value;state.trips={};state.standaloneTrips={};state.refined={};state.selectedTrip=null;render();toast('Режим изменён. Запустите новый расчёт явно.');return;}
  if(a==='calculate'){calculate();return;}
  if(a==='retry-trip'){state.tab='trips';calculateOne(el.dataset.key);toast('Повторяем только выбранную поездку.');return;}
  if(a==='retry-profile'){loadProfile(el.dataset.side);return;}
  if(a==='clear-results'){state.scenario==='standalone'?state.standaloneTrips={}:state.trips={};state.selectedTrip=null;render();toast('Результаты очищены. Адреса и цели сохранены.');return;}
  if(a==='show-route'){state.selectedTrip=el.dataset.key;state.view='map';render();$('.map-section').scrollIntoView({behavior:'smooth',block:'start'});toast('Показана модельная уличная часть. Подходы неизвестны.');return;}
  if(a==='trip-detail'){state.selectedTrip=el.dataset.key;render();$('.trip-detail')?.scrollIntoView({behavior:'smooth',block:'nearest'});return;}
  if(a==='close-trip-detail'){state.selectedTrip=null;render();return;}
  if(a==='map-goal'){state.tab='trips';renderResults();toast(`Цель: ${selectedGoals().find(g=>g.id===el.dataset.goal)?.label}. Поездки доступны в результатах.`);return;}
  if(a==='tab'){state.tab=el.dataset.value;state.collapsed=false;state.detail=null;renderResults();$(`[data-action="tab"][data-value="${state.tab}"]`).focus({preventScroll:true});return;}
  if(a==='collapse'){state.collapsed=!state.collapsed;renderResults();return;}
  if(a==='metric'){state.detail=state.detail===el.dataset.metric?null:el.dataset.metric;renderResults();$(`[data-metric="${el.dataset.metric}"]`).focus({preventScroll:true});return;}
  if(a==='metric-map'){state.view='map';const layer=$('#'+el.dataset.layer);layer.style.visibility='visible';$(`[data-layer="${el.dataset.layer}"]`).checked=true;renderResults();$('.map').classList.add('map-focus');$('.map-section').scrollIntoView({behavior:'smooth',block:'start'});toast('Категория показана на схеме. Все объекты демонстрационные.');return;}
  if(a==='sources'){sources();return;}
  if(a==='layers'){const menu=$('#layer-menu');menu.hidden=!menu.hidden;el.setAttribute('aria-expanded',!menu.hidden);return;}
  if(a==='map-reset'){state.mapZoom=false;state.selectedTrip=null;state.pick=null;$('.map').classList.remove('map-focus');render();toast('Показаны все выбранные места.');return;}
  if(a==='refine'){refine(el.dataset.key,el.dataset.end);return;}
  if(a==='choose-street'){state.refined[el.dataset.key+':'+el.dataset.end]=true;state.selectedTrip=el.dataset.key;closeDialog();calculateOne(el.dataset.key,false,true);toast('Точка выбрана явно. Перепроверяем только эту поездку.');return;}
  if(a==='street-map'){beginPick('street',{key:el.dataset.key,end:el.dataset.end});return;}
  if(a==='pick-point'){beginPick('point');return;}
  if(a==='pick-start'){beginPick('start');return;}
  if(a==='confirm-map-point'){confirmPick();return;}
  if(a==='cancel-pick'){state.pick=null;render();return;}
  if(a==='point-calculate'){if(!state.point)return;const token=++state.pointRun;state.pointReady='loading';state.view='results';render();focusResults();setTimeout(()=>{if(token!==state.pointRun)return;state.pointReady=true;render();announce('Остановки вокруг точки найдены в демо-наборе.');},900);return;}
  if(a==='about'){openDialog('PlaceLens · самостоятельный макет','Одна дизайн-версия · 27 октября 2026',`<p>Прототип помогает пройти путь от адреса к сравнению окружения и поездок. Все значения, геометрия и ID синтетические. Реального backend, тайлов и геоаналитики здесь нет.</p><h3>Что попробовать</h3><p>Найти адрес → открыть профиль → добавить Б → задать общие цели → рассчитать → уточнить улицу. В меню «···» доступны загрузка, частичный отказ и ошибка профиля Б.</p><h3>Визуальные ориентиры</h3><ul class="ref-list"><li><a href="https://www.google.com/maps" target="_blank" rel="noopener">Google Maps</a>: просмотрен интерфейс маршрутов. Компактный ввод рядом с картой, общий выбор способа передвижения.</li><li><a href="https://denzify.com/sample" target="_blank" rel="noopener">Denzify, открытый отчёт</a>: просмотрен настоящий образец с картой и методикой. Иерархия фактов и заметная связь с источниками.</li></ul><p>Матрица А/Б и мобильные парные строки спроектированы под PlaceLens. Рейтинги и оценочные вердикты не используются.</p><p>Данные не сохраняются после закрытия страницы. Поисковый каталог намеренно мал. Выбор точки на схеме имитирует реальную карту.</p>`);return;}
});
document.addEventListener('change',e=>{if(e.target.dataset.layer)$('#'+e.target.dataset.layer).style.visibility=e.target.checked?'visible':'hidden';});
$('#map-art').addEventListener('click',e=>{if(!state.pick||e.target.closest('button'))return;const r=$('#map-art').getBoundingClientRect();confirmPick(Math.max(10,Math.min(90,(e.clientX-r.left)/r.width*100)),Math.max(15,Math.min(80,(e.clientY-r.top)/r.height*100)));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.open){if(state.pick){state.pick=null;render();toast('Выбор точки отменён.');}else if(!$('#layer-menu').hidden){$('#layer-menu').hidden=true;$('[data-action="layers"]').setAttribute('aria-expanded','false');$('[data-action="layers"]').focus();}}if(e.key==='ArrowDown'&&e.target.classList.contains('search-result')){e.preventDefault();e.target.nextElementSibling?.focus();}if(e.key==='ArrowUp'&&e.target.classList.contains('search-result')){e.preventDefault();(e.target.previousElementSibling||$('#search')).focus();}});
if(new URLSearchParams(location.search).get('demo'))demo(new URLSearchParams(location.search).get('demo')==='partial'?'partial':'filled');else render();
